function contientDoublon(arr) {
  const vus = new Set(); // O(n) en temps, O(n) en espace
  for (const x of arr) {
    if (vus.has(x)) return true;
    vus.add(x);
  }
  return false;
}

contientDoublon([]); // Cas limite : tableau vide, la boucle ne s'exécute jamais
contientDoublon([5, 5]); // Cas avec doublon dès le 2e élément

// Pile avec un tableau
const pile = [];
pile.push('a'); pile.push('b');
pile.pop(); // 'b' (LIFO)

// File avec un tableau (shift coûte O(n) — à connaître en entretien !)
const file = [];
file.push('a'); file.push('b');
file.shift(); // 'a' (FIFO)

pile.pop(); // 'a' — la pile est maintenant vide
pile.pop(); // undefined — cas limite : pop() sur une pile vide ne lève pas d'erreur en JS

function bfs(graphe, depart) {
  const visites = new Set([depart]);
  const file = [depart];
  while (file.length) {
    const noeud = file.shift();
    for (const voisin of graphe[noeud]) {
      if (!visites.has(voisin)) {
        visites.add(voisin);
        file.push(voisin);
      }
    }
  }
  return visites;
}

function fusionner(gauche, droite) {
  const res = [];
  while (gauche.length && droite.length) {
    res.push(gauche[0] <= droite[0] ? gauche.shift() : droite.shift());
  }
  return [...res, ...gauche, ...droite];
}

function triFusion(arr) {
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  return fusionner(triFusion(arr.slice(0, mid)), triFusion(arr.slice(mid)));
}
